class Solution {
    fun countSubarrays(nums:IntArray,k:Int):Int{
        val pivot=nums.indexOf(k);
        val frequency=HashMap<Int,Int>();
        frequency[0]=1;
        var balance=0;
        for(i in pivot-1 downTo 0){
            balance+=if(nums[i]>k)1 else -1;
            frequency[balance]=(frequency[balance]?:0)+1
        };
        var answer=0L;
        balance=0;
        for(i in pivot until nums.size){
            if(i>pivot)balance+=if(nums[i]>k)1 else -1;
            answer+=(frequency[-balance]?:0)+(frequency[1-balance]?:0)
        };
        return answer.toInt()
    }
}

